sqlite3 shop.db "WITH s AS (SELECT c.label k, SUM(l.qty*l.unit_price_cents) v FROM sale s JOIN sale_line l ON l.sale_id=s.id JOIN product p ON p.sku=l.sku JOIN cat c ON c.id=p.cat_id WHERE s.placed_at LIKE '2026-03-%' GROUP BY 1), r AS (SELECT c.label k, SUM(r.amount_cents) v FROM refund r JOIN sale s ON s.id=r.sale_id JOIN product p ON p.sku=r.sku JOIN cat c ON c.id=p.cat_id WHERE s.placed_at LIKE '2026-03-%' GROUP BY 1) SELECT s.k || ' ' || printf('%.2f', (s.v - IFNULL(r.v,0))/100.0) FROM s LEFT JOIN r USING (k) ORDER BY s.v - IFNULL(r.v,0) DESC LIMIT 1" > answer.txt
